const $ = id => document.getElementById(id);
let memories = [];
let signature = '';
const stamp = value => new Date(value).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'});
function el(tag,cls,text){const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}
function photo(row){$('full-photo').src='/api/image/'+row.id;$('photo-caption').textContent='Approximately '+stamp(row.captured_at)+' · '+row.scene.summary;$('photo-dialog').showModal();}
$('close-photo').onclick=()=>$('photo-dialog').close();
function card(row){const item=el('article','memory');const img=el('img');img.src='/api/image/'+row.id;img.alt=row.scene.summary;img.loading='lazy';img.tabIndex=0;img.onclick=()=>photo(row);img.onkeydown=e=>{if(e.key==='Enter')photo(row);};item.append(img,el('time','', 'About '+stamp(row.captured_at)),el('p','',row.scene.summary));if(row.scene.view_quality==='uncertain')item.append(el('span','quality','Uncertain view'));return item;}
async function refresh(){try{const response=await fetch('/api/memories');if(!response.ok)throw Error();const data=await response.json();memories=data.memories;$('count').textContent=data.count;$('connection').textContent='● Memory connected';const next=memories.map(m=>m.id).join();if(next!==signature){signature=next;$('memories').replaceChildren(...memories.map(card));}}catch(e){$('connection').textContent='Computer service disconnected';}}
for(const b of document.querySelectorAll('.examples button'))b.onclick=()=>{$('question').value=b.textContent;$('question').focus();};
$('question').onkeydown=e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();$('ask-form').requestSubmit();}};
$('ask-form').onsubmit=async e=>{e.preventDefault();if($('ask').disabled)return;const question=$('question').value.trim();if(!question)return;$('ask').disabled=true;const area=$('answers');area.querySelector('.empty-answer')?.remove();const item=el('article','answer');item.append(el('p','question-text',question));const pending=el('p','pending','Looking through recorded views…');item.append(pending);area.prepend(item);try{const response=await fetch('/api/ask',{method:'POST',headers:{'Content-Type':'application/json','X-Spatial-UI':'1'},body:JSON.stringify({question})});const data=await response.json();if(!response.ok)throw Error(data.error||'Could not answer.');pending.remove();item.append(el('p','answer-text',data.answer));const sources=el('div','sources');for(const row of data.evidence){const button=el('button','source');button.type='button';const img=el('img');img.src='/api/image/'+row.id;img.alt=row.scene.summary;button.append(img,el('span','', 'About '+stamp(row.captured_at)));button.onclick=()=>photo(row);sources.append(button);}item.append(sources);const method=data.route==='hot_index'?'Fast last-seen index':data.route==='model'?'Photo review':'No recorded views';item.append(el('p','answer-meta',`${method} · ${data.evidence.length} supporting views · ${data.searched_count} of ${data.total_count} memories searched`));if(data.insufficient_evidence)item.append(el('span','quality','Evidence is limited'));}catch(error){pending.className='error';pending.textContent=error.message;}finally{$('ask').disabled=false;}};
refresh();setInterval(refresh,5000);
